 static AmbienteBanco Bank(bool qas)=>qas?AmbientesBanco.Qas120:AmbientesBanco.Dev110;
 static AmbienteSap Sap(bool qas)=>qas?AmbientesSap.Qas120:AmbientesSap.Dev110;
 static IConfiguration Config(bool qas)=>new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{["Sap:BaseUrl"]=Sap(qas).Origem,["Sap:SapClient"]=Sap(qas).SapClient}).Build();
 static NpgsqlConnectionStringBuilder Connection(bool qas)=>new(){Host="127.0.0.1",Port=5433,Database=Bank(qas).Banco,Username=Bank(qas).PapelAcm,SearchPath="fugates",Enlist=false,Options="-c default_transaction_read_only=on",Passfile="/SYNTHETIC-NOT-ACCESSED/passfile"};
 static IConfigurationRoot Provider(bool qas,NpgsqlConnectionStringBuilder? connection=null)
 {
  var data=Config(qas).AsEnumerable().ToDictionary(x=>x.Key,x=>x.Value);
  foreach(var key in new[]{"FUGATES_INTEGRATION_WORKER_ENABLED","INC005_WORKER_ENABLED","FUGATES_CARRIER_SYNC_ENABLED","CARRIER_WORKER_ENABLED","Sap:Enabled","AcmR104:ExecutionAuthorized"})data[key]="false";
  data["AcmR165R:CredentialSecurityCleared"]="true";data["AcmR165R:ApprovalReference"]="SYNTHETIC-OFFLINE";
  data["HostIntegracao:PersistenceMode"]="PostgreSql";data["HostIntegracao:ExternalMode"]="Fake";data["AcmR57:Enabled"]="true";
  data["ConnectionStrings:FugaTES"]=(connection??Connection(qas)).ConnectionString;
  return new ConfigurationBuilder().AddInMemoryCollection(data).Build();
 }
