 [Theory][InlineData(false)][InlineData(true)] public void Provider_keeps_cluster_host_schema_passfile_and_readonly_guards(bool qas)
 {
  foreach(var mutate in new Action<NpgsqlConnectionStringBuilder>[] {c=>c.Port=5432,c=>c.Port=5434,c=>c.Host="192.168.17.40",c=>c.SearchPath="public",c=>c.Passfile="",c=>c.Password="synthetic",c=>c.Options="",c=>c.Enlist=true})
