 }
 [Theory][InlineData(false)][InlineData(true)] public void ACM_command_derives_database_from_SAP_and_keeps_private_passfile(bool qas)
 {var profile=new AcmManualRetryCommandProfile{Passfile="/SYNTHETIC/passfile"};var runtime=AcmManualRetryCommandHost.BuildRuntimeConfiguration(profile,Config(qas));var c=new NpgsqlConnectionStringBuilder(runtime.GetConnectionString("FugaTES"));Assert.Equal(Bank(qas).Banco,c.Database);Assert.Equal(Bank(qas).PapelAcm,c.Username);Assert.Equal(profile.Passfile,c.Passfile);Assert.Null(c.Password);Assert.Equal(5433,c.Port);Assert.Equal("127.0.0.1",c.Host);Assert.Equal("fugates",c.SearchPath);Assert.Equal("false",runtime["FUGATES_INTEGRATION_WORKER_ENABLED"]);using var source=NpgsqlDataSourceFactory.CriarAcm(c.ConnectionString,Bank(qas));}
