 [Theory][InlineData(false)][InlineData(true)] public async Task MM_SAP_transport_cannot_leave_selected_environment(bool qas)
 {var handler=new Capture();using var http=new HttpClient(new MmSapOnlyHandler(handler,Sap(qas)));var route="/sap/opu/odata4/sap/api_purchaseorder_2/srvd_a2x/sap/purchaseorder/0001/PurchaseOrder";using var response=await http.GetAsync(Sap(qas).Origem+route+"?sap-client="+Sap(qas).SapClient);Assert.Equal(1,handler.Calls);await Assert.ThrowsAsync<InvalidOperationException>(()=>http.GetAsync(Sap(!qas).Origem+route+"?sap-client="+Sap(!qas).SapClient));Assert.Equal(1,handler.Calls);}
