 [Theory][InlineData(false)][InlineData(true)] public void Bound_MM_cache_cannot_read_or_overwrite_other_environment(bool qas)
 {var dir=Path.Combine(Path.GetTempPath(),"FugaTES-environment-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var snapshot=new MmPurchaseOrderSnapshot{Origin=Sap(qas).Origem,Client=Sap(qas).SapClient};new MmFileSnapshotStore(dir).Write(snapshot);var bound=new MmFileSnapshotStore(dir,ambiente:Sap(qas));Assert.Equal(snapshot.Origin,bound.Read().Origin);Assert.Throws<InvalidOperationException>(()=>new MmFileSnapshotStore(dir,readOnly:true,ambiente:Sap(!qas)).Read());Assert.Throws<InvalidOperationException>(()=>bound.Write(snapshot with{Origin=Sap(!qas).Origem,Client=Sap(!qas).SapClient}));}finally{Directory.Delete(dir,true);}}
