 [Theory][InlineData(false)][InlineData(true)] public void MM_runtime_credentials_and_policy_scope_are_explicit(bool qas)
 {var a=Bank(qas);var d=MmRetryPolicyFile.RuntimeDirectoryFor(a);var mode=UnixFileMode.UserRead|UnixFileMode.UserExecute;Assert.True(CarrierSystemdCredentials.IsApprovedMmRuntimeDirectory("carrier-hml-sap-password",d,d,mode,mode,false,a));Assert.False(CarrierSystemdCredentials.IsApprovedMmRuntimeDirectory("carrier-hml-sap-password",d,d,mode,mode,false,Bank(!qas)));Assert.True(MmRetryPolicyFile.ApprovedRuntimeScope(d+"/mm-retry-policy",d,UnixFileMode.UserRead,mode,false,a));Assert.False(MmRetryPolicyFile.ApprovedRuntimeScope(d+"/mm-retry-policy",MmRetryPolicyFile.RuntimeDirectoryFor(Bank(!qas)),UnixFileMode.UserRead,mode,false,a));Assert.False(MmRetryPolicyFile.ApprovedRuntimeScope(d+"/mm-retry-policy",d,UnixFileMode.UserRead,mode,false,Bank(!qas)));Assert.False(MmRetryPolicyFile.ApprovedRuntimeScope(d+"/mm-retry-policy",d,UnixFileMode.UserRead,mode,true,a));}
 [Theory][InlineData(false)][InlineData(true)] public void Synthetic_physical_frame_requires_its_expected_environment(bool qas)
 {var p=PilotPlan.Create();var id=Guid.NewGuid();var a=Bank(qas);var f=new PhysicalFrame{RunId=p.RunId,IntegrationId=id,Contract=p.Contract,Description=p.Description,H4Version=1,ReadOnly=true,Cluster="18/fugatesacmdev",Port=5433,Database=a.Banco,Role=a.PapelAcm,Fingerprint=new string('A',64),CorrelationId="r165ag:cpi:"+p.RunId.ToString("N")+":"+Guid.NewGuid().ToString("N"),CapturedUtc=DateTimeOffset.UtcNow};f.Validate(p,id,a);Assert.Throws<InvalidOperationException>(()=>(f with{Database=a.Banco+" "}).Validate(p,id,a));Assert.Throws<InvalidOperationException>(()=>f.Validate(p,id,Bank(!qas)));Assert.Throws<InvalidOperationException>(()=>(f with{Database=Bank(!qas).Banco}).Validate(p,id,a));Assert.Throws<InvalidOperationException>(()=>(f with{Role=Bank(!qas).PapelAcm}).Validate(p,id,a));}
 [Theory][InlineData(false)][InlineData(true)] public async Task VM_query_factory_passes_its_selected_environment_to_the_SAP_adapter(bool qas)
 {var s=Sap(qas);var a=Bank(qas);var options=new MmLinuxOptions{SapOrigin=s.Origem,SapClient=s.SapClient,Database=a.Banco,Role=a.PapelMm,StateDirectory=qas?"/var/lib/fugates-mm-qas":"/var/lib/fugates-mm"};var wire=new PedidosCompraMmTests.Transport(_=>PedidosCompraMmTests.Page(PedidosCompraMmTests.Header()));using var http=new HttpClient(wire);var result=await MmLinuxRuntime.CreateQuery(options,http,new NoAuth()).ConsultarAsync(default);Assert.True(result.Sucesso,result.Codigo);var uri=Assert.Single(wire.Uris);Assert.Equal(new Uri(s.Origem).Host,uri.Host);Assert.Contains("sap-client="+s.SapClient,uri.Query);}
 [Theory][InlineData(false)][InlineData(true)] public void Motor_composition_uses_only_the_database_of_its_SAP_process(bool qas)
 {var cfg=Provider(qas);cfg["MotorIntegracao:LeaseDuration"]="00:01:00";cfg["MotorIntegracao:LeaseRenewInterval"]="00:00:20";cfg["MotorIntegracao:RetryBackoff"]="00:01:00";cfg["TimeoutProcessamentoIntegracao:Timeout"]="00:00:10";cfg["HostIntegracao:PollInterval"]="00:00:30";cfg["HostIntegracao:ShutdownGracePeriod"]="00:00:10";var services=new ServiceCollection();HostIntegracaoComposition.ConfigurarServicos(services,cfg);using(var sp=services.BuildServiceProvider()){var c=new NpgsqlConnectionStringBuilder(sp.GetRequiredService<NpgsqlDataSource>().ConnectionString);Assert.Equal(Bank(qas).Banco,c.Database);Assert.Equal(Bank(qas).PapelAcm,c.Username);}cfg["ConnectionStrings:FugaTES"]=Connection(!qas).ConnectionString;var crossed=new ServiceCollection();HostIntegracaoComposition.ConfigurarServicos(crossed,cfg);using var bad=crossed.BuildServiceProvider();Assert.Throws<InvalidOperationException>(()=>bad.GetRequiredService<NpgsqlDataSource>());}
 [Theory][InlineData(false)][InlineData(true)] public void Monitor_cannot_use_another_valid_profile_in_an_already_selected_process(bool qas)
 {var a=Bank(!qas);var p=new AcmMonitorProfile{SapOrigin=Sap(!qas).Origem,SapClient=Sap(!qas).SapClient,Database=a.Banco,Role=a.PapelAcm,Enabled=true,LocalPort=15433,CredentialTarget="FugaTES/HML/ACM/PostgreSQL",ClearanceReference="SYNTHETIC",TransportPolicyReference="SYNTHETIC",TransportSslMode="Require"};bool read=false;using var session=AcmMonitorSession.Criar(p,(_,_)=>{read=true;return "SYNTHETIC";},Sap(qas));Assert.False(session.Configurado);Assert.False(read);}
 sealed class NoAuth:FugaTES.Integracao.SAP.Autenticacao.IAutenticacaoSap {public Task AplicarAsync(HttpRequestMessage request,CancellationToken ct)=>Task.CompletedTask;}
 sealed class Capture:HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){Calls++;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK));}}
 sealed class Envelope(AmbienteBanco a):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=JsonContent.Create(new DevReadEnvelope<object[]>(new("18/fugatesacmdev",5433,a.Banco,a.PapelLeitura,true,DateTimeOffset.UtcNow),[]))});}
